from __future__ import annotations

import uuid

from fastapi import FastAPI, Header, HTTPException, Request, status
from fastapi.responses import JSONResponse

from stockflow.routers import health, orders, products

app = FastAPI(title="StockFlow Mini", version="0.1.0")


@app.middleware("http")
async def extract_tenant_id(request: Request, call_next):
    """Extract tenant_id from X-Tenant-Id header and inject into request state."""
    tenant_id_header = request.headers.get("X-Tenant-Id")
    if not tenant_id_header:
        return JSONResponse(
            status_code=status.HTTP_400_BAD_REQUEST,
            content={
                "error": {
                    "code": "INVALID_TENANT",
                    "message": "X-Tenant-Id header is required",
                    "details": {},
                }
            },
        )
    try:
        tenant_id = uuid.UUID(tenant_id_header)
    except (ValueError, AttributeError):
        return JSONResponse(
            status_code=status.HTTP_400_BAD_REQUEST,
            content={
                "error": {
                    "code": "INVALID_TENANT",
                    "message": "X-Tenant-Id must be a valid UUID",
                    "details": {},
                }
            },
        )
    request.state.tenant_id = tenant_id
    response = await call_next(request)
    return response


@app.exception_handler(HTTPException)
async def http_exception_handler(request: Request, exc: HTTPException):
    """Custom HTTP exception handler for consistent error format."""
    if isinstance(exc.detail, dict) and "error" in exc.detail:
        return JSONResponse(
            status_code=exc.status_code,
            content=exc.detail,
        )
    return JSONResponse(
        status_code=exc.status_code,
        content={
            "error": {
                "code": "INTERNAL_ERROR",
                "message": str(exc.detail),
                "details": {},
            }
        },
    )


@app.exception_handler(Exception)
async def generic_exception_handler(request: Request, exc: Exception):
    """Handle unexpected exceptions."""
    return JSONResponse(
        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        content={
            "error": {
                "code": "INTERNAL_ERROR",
                "message": "An unexpected error occurred",
                "details": {},
            }
        },
    )


# Include routers
app.include_router(products.router)
app.include_router(orders.router)
app.include_router(health.router)


@app.get("/")
def root() -> dict[str, str]:
    """Root endpoint."""
    return {"message": "StockFlow Mini API", "version": "0.1.0"}

