) -> OrderResponse:
    """Get an order by ID with items. Only returns orders belonging to the tenant."""
    order = db.execute(
        select(Order)
        .where(Order.id == order_id, Order.tenant_id == tenant_id)
        .options(selectinload(Order.items))
    ).scalars().first()

    if order is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={
                "error": {
                    "code": "NOT_FOUND",
                    "message": f"Order '{order_id}' not found",
                    "details": {"order_id": str(order_id)},
                }
            },
        )

    return order


@router.post("/{order_id}/cancel", response_model=OrderResponse)
def cancel_order(
    order_id: uuid.UUID,
    tenant_id: uuid.UUID = Depends(get_tenant_id),
    db: Session = Depends(get_db),
) -> OrderResponse:
    """Cancel an order. Only PENDING orders can be cancelled. Restores stock."""
    order = db.execute(
        select(Order)
        .where(Order.id == order_id, Order.tenant_id == tenant_id)
        .options(selectinload(Order.items))
    ).scalars().first()

    if order is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={
                "error": {
                    "code": "NOT_FOUND",
                    "message": f"Order '{order_id}' not found",
                    "details": {"order_id": str(order_id)},
                }
            },
        )

    if order.status != "PENDING":
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "error": {
                    "code": "INVALID_ORDER_STATE",
                    "message": f"Order '{order_id}' cannot be cancelled (status: {order.status})",
                    "details": {"order_id": str(order_id), "current_status": order.status},
                }
            },
        )

    # Update status to CANCELLED
    order.status = "CANCELLED"

    # Restore stock for all items
    for item in order.items:
        db.execute(
            update(Product)
            .where(Product.id == item.product_id, Product.tenant_id == tenant_id)
            .values(stock=Product.stock + item.quantity)
        )

    db.commit()
    db.refresh(order)

    # Reload with items
    order = db.execute(
        select(Order)
        .where(Order.id == order.id)
        .options(selectinload(Order.items))
    ).scalars().first()

    return order

